const { withAppBuildGradle } = require('expo/config-plugins');

/** Release builds sign with Daily's upload key, named by DAILY_* in ~/.gradle/gradle.properties (outside the repo: android/
 * is regenerated by prebuild and the repo is public). Without those properties they fall back to the debug key, so a
 * machine without the key still builds; Play rejects such a bundle, which is the point. */
module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (c) => {
    let g = c.modResults.contents;
    if (g.includes('DAILY_STORE_FILE')) return c;
    const signing = g.replace('signingConfigs {\n', `signingConfigs {
        release {
            if (findProperty('DAILY_STORE_FILE')) {
                storeFile file(findProperty('DAILY_STORE_FILE'))
                storePassword findProperty('DAILY_STORE_PASSWORD')
                keyAlias findProperty('DAILY_KEY_ALIAS')
                keyPassword findProperty('DAILY_KEY_PASSWORD')
            }
        }
`);
    const used = signing.replace(/(buildTypes \{[\s\S]*?release \{\n(?:\s*\/\/.*\n)*\s*)signingConfig signingConfigs\.debug/,
      "$1signingConfig findProperty('DAILY_STORE_FILE') ? signingConfigs.release : signingConfigs.debug");
    if (signing === g || used === signing) throw new Error('withReleaseSigning: build.gradle no longer matches; update the plugin');
    c.modResults.contents = used;
    return c;
  });
};
